[CmdletBinding()]
param([Parameter(Mandatory)][string]$OutputDirectory,
      [string]$Bazel='',
      [string]$RepoContentsCache,
      [string]$BazelOutputBase,
      [string[]]$Only)
$ErrorActionPreference='Stop'
if (!$Bazel) { Import-Module (Join-Path $PSScriptRoot '../setup/Es2Bazel.psm1') -Force; $Bazel=Resolve-Es2Bazel }
if (!$env:ES2_DATA_ROOT) { throw 'ES2_DATA_ROOT is required for mutation checks.' }
$repo=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../../..'))
$output=[IO.Path]::GetFullPath($OutputDirectory)
if (!(Test-Path -LiteralPath $output -PathType Container)) { throw 'An existing scratch directory is required.' }
$cases=@(
    @{Name='rng_next'; File='rng.c'; Old='return value;'; New='return value ^ 1u;'; Why='Flips a returned random bit while retaining state.'},
    @{Name='rng_bounded'; File='rng.c'; Old='return masked % (int32_t)bound;'; New='return (masked % (int32_t)bound) ^ 1;'; Why='Flips the remainder result, including zero.'},
    @{Name='dist2d_point'; File='geometry.c'; Old='return es2_distance2(read32(p) - read32(q), read32(p + 4) - read32(q + 4));'; New='return es2_distance2(read32(p) - read32(q) + 1u, read32(p + 4) - read32(q + 4));'; Why='Shifts the first point delta by one.'},
    @{Name='dist2d_vector'; File='geometry.c'; Old='return es2_distance2(read32(p), read32(p + 4));'; New='return es2_distance2(read32(p) ^ 1u, read32(p + 4));'; Why='Changes the first vector component.'},
    @{Name='dist2d_delta'; File='geometry.c'; Old='a + sar(b, 1);'; New='a + sar(b, 2);'; Why='Uses one quarter rather than one half of the minor magnitude.'},
    @{Name='dist_octagonal'; File='geometry.c'; Old='a + sar(b, 1);'; New='a + sar(b, 2);'; Why='Uses one quarter rather than one half of the minor magnitude.'},
    @{Name='dist_gate'; File='geometry.c'; Old='read32(p + 8) - read32(q + 8)'; New='read32(p + 8) - read32(q + 8) + 1u'; Why='Changes the third point delta.'},
    @{Name='time_scale'; File='timing.c'; Old='low < 64 ? 64'; New='low < 64 ? 65'; Why='Changes the lower clamped value from 64 to 65.'},
    @{Name='timer_word_step'; File='timing.c'; Old='read_value(p, 2) - (uint32_t)scale'; New='read_value(p, 2) - ((uint32_t)scale + 1u)'; Why='Subtracts an extra tick before saturation.'},
    @{Name='timer_dword_step'; File='timing.c'; Old='read_value(p, 4) - (uint32_t)signed_word(scale)'; New='read_value(p, 4) - ((uint32_t)signed_word(scale) + 1u)'; Why='Subtracts an extra tick before saturation.'},
    @{Name='timer_arm'; File='timing.c'; Old='(uint32_t)signed_word(duration) << 11'; New='(uint32_t)signed_word(duration) << 10'; Why='Halves the stored nonzero duration.'},
    @{Name='heading_cos'; File='movement.c'; Old='return negative ? 0u-value : value;'; New='return (negative ? 0u-value : value) ^ 1u;'; Why='Flips a cosine result bit.'},
    @{Name='heading_sin'; File='movement.c'; Old='angle-0x4000u'; New='angle-0x3ff0u'; Why='Changes the quarter-turn offset by one table index.'},
    @{Name='multiply_q8'; File='movement.c'; Old='signed32(a)*signed32(b))>>8'; New='signed32(a)*signed32(b))>>7'; Why='Changes the fixed-point scale for nonzero products.'},
    @{Name='movement_step'; File='movement.c'; Old='n > 32767 ? 32767 : n'; New='n > 32767 ? 32766 : n'; Why='Changes the positive saturation result.'},
    @{Name='hud_speed'; File='movement.c'; Old='signed16(read16(a+0x28e))*maximum'; New='(signed16(read16(a+0x28e))+1)*maximum'; Why='Changes the word-path speed input.'},
    @{Name='transform_point'; File='movement.c'; Old='value+read32(m+20+4*row)'; New='value+read32(m+20+4*row)+1u'; Why='Adds one to every transformed coordinate.'},
    @{Name='vector_subtract'; File='movement.c'; Old='write32(p,read32(p)-read32(q));'; New='write32(p,read32(p)-read32(q)+1u);'; Why='Changes the first subtracted coordinate.'},
    @{Name='distance_display'; File='geometry.c'; Old='return es2_distance2(read32(p) - read32(q), read32(p + 4) - read32(q + 4));'; New='return es2_distance2(read32(p) - read32(q) + 1u, read32(p + 4) - read32(q + 4));'; Why='Changes the displayed point distance input.'},
    @{Name='matrix_compose'; File='matrix.c'; Old='sum>>14)+fx_r32(b+20+4*row)'; New='sum>>14)+fx_r32(b+20+4*row)+1u'; Why='Adds one to composed translation on the rotation path.'},
    @{Name='rotate_point'; File='matrix.c'; Old='fx_w32(q+4*row,value);'; New='fx_w32(q+4*row,value^1u);'; Why='Flips a rotated coordinate bit.'},
    @{Name='matrix_transpose'; File='matrix.c'; Old='fx_w16(m+pairs[i][1],a);'; New='fx_w16(m+pairs[i][1],a^1u);'; Why='Corrupts a transposed coefficient.'},
    @{Name='pose_matrix'; File='matrix.c'; Old='fx_w32(m+28,z);'; New='fx_w32(m+28,z^1u);'; Why='Changes translation Z by one bit.'},
    @{Name='scalar_interpolate'; File='pose.c'; Old='(uint32_t)(numerator/den)+y0'; New='(uint32_t)(numerator/den)+y0+1u'; Why='Changes the interpolated scalar by one.'},
    @{Name='track_count'; File='pose.c'; Old='while(count<10 &&'; New='while(count<9 &&'; Why='Drops the tenth occupied track.'},
    @{Name='inverse_sine'; File='trig.c'; Old='return signed_value<0 ? 0u-angle : angle;'; New='return (signed_value<0 ? 0u-angle : angle)^1u;'; Why='Changes a small-table result bit.'},
    @{Name='angle_ratio'; File='trig.c'; Old='((angle<<2)&65535)'; New='((angle<<1)&65535)'; Why='Halves nonzero output angles.'},
    @{Name='matrix_angles'; File='trig.c'; Old='fx_w16(a,pitch);'; New='fx_w16(a,pitch^1u);'; Why='Changes the stored pitch.'},
    @{Name='approach_word'; File='energy.c'; Old='value=(uint16_t)(value+step);'; New='value=(uint16_t)(value+step+1u);'; Why='Advances rising values by one extra before clamping.'},
    @{Name='energy_accumulate'; File='energy.c'; Old='if(delta>=5) delta=5;'; New='if(delta>=5) delta=4;'; Why='Changes the capped request value, not only a tie comparison.'},
    @{Name='clip_pose'; File='pose.c'; Old='m->write16(c,track+0x20u,1);'; New='m->write16(c,track+0x20u,0);'; Why='Disables a successfully loaded clip.'},
    @{Name='pose_parent'; File='track.c'; Old='local_translation(local, (const uint8_t *)pose + 6);'; New='local_translation(local, (const uint8_t *)pose + 6); fx_w32(local+20,fx_r32(local+20)^1u);'; Why='Changes local translation before parent composition.'},
    @{Name='track_forward'; File='track.c'; Old='return track_pose(t, table, padding, 0);'; New='return track_pose(t, table, padding, 1);'; Why='Applies inverse instead of forward transform.'},
    @{Name='track_inverse'; File='track.c'; Old='return track_pose(t, table, padding, 1);'; New='return track_pose(t, table, padding, 0);'; Why='Applies forward instead of inverse transform.'},
    @{Name='track_scaled'; File='track.c'; Old='fx_w32(o + 28, fx_r32(t + 0x4a));'; New='fx_w32(o + 28, fx_r32(t + 0x4a)^1u);'; Why='Changes disabled-track copied translation Z.'},
    @{Name='track_scaled_inverse'; File='track.c'; Old='copy_matrix(t + 0x2e, input);'; New='copy_matrix(t + 0x2e, input); fx_w32(t+0x42,fx_r32(t+0x42)^1u);'; Why='Changes disabled-track copied translation X.'},
    @{Name='manager_reset'; File='animation.c'; Old='m->write32(c, matrix + 0x1cu, fx_r32(in + 0x1c));'; New='m->write32(c, matrix + 0x1cu, fx_r32(in + 0x1c)^1u);'; Why='Changes copied manager translation Z.'},
    @{Name='animation_step'; File='animation.c'; Old='fx_w32(a + 0x2e, fx_r32(point + 8));'; New='fx_w32(a + 0x2e, fx_r32(point + 8)^1u);'; Why='Changes the resulting actor position Z.'},
    @{Name='actor_animate'; File='animation.c'; Old='if (!(R16(actor + 0x38u) >> 8))'; New='if (!(R16(actor + 0x38u) & 0xffu))'; Why='Uses the low enable byte instead of the high byte.'},
    @{Name='ground_animate'; File='animation.c'; Old='es2_movement_step(100, scale)'; New='es2_movement_step(101, scale)'; Why='Changes the ground animation rate input.'},
    @{Name='actor_rollback'; File='animation.c'; Old='return copy_actor(m, actor, block, quarter, 0);'; New='return copy_actor(m, actor, block, quarter, 1);'; Why='Saves state instead of restoring it.'},
    @{Name='euler_matrix'; File='matrix.c'; Old='fx_w16(m,16384);'; New='fx_w16(m,16385);'; Why='Changes the identity diagonal coefficient.'},
    @{Name='pose_interpolate'; File='pose.c'; Old='fx_sar(delta*fraction,10)'; New='fx_sar(delta*(fraction^1u),10)'; Why='Changes interpolation fraction bit zero.'},
    @{Name='multiply_q10'; File='energy.c'; Old='(uint32_t)(p>>10)'; New='((uint32_t)(p>>10)^1u)'; Why='Flips the multiply result bit zero.'},
    @{Name='track_advance'; File='animation.c'; Old='if (fx_s16((uint32_t)first) > fx_s16(eax)) {'; New='if (fx_s16((uint32_t)first) < fx_s16(eax)) {'; Why='Reverses track endpoint ordering.'},
    @{Name='track_advance'; File='animation.c'; Old='if ((uint16_t)eax == R16(t + 6u) || (uint16_t)eax == 0xffffu) W16('; New='if ((uint16_t)eax == R16(t + 6u)) W16('; Why='Removes the sentinel completion condition.'},
    @{Name='track_target'; File='animation.c'; Old='fx_s16(b) > fx_s16(a) :'; New='fx_s16(b) >= fx_s16(a) :'; Why='Changes the chosen direction when endpoint words tie.'},
    @{Name='track_rate'; File='animation.c'; Old='if ((fx_s16(rate) < 0) == (fx_s16(old) < 0))'; New='if ((fx_s16(rate) <= 0) == (fx_s16(old) < 0))'; Why='Treats zero rate as negative in the sign transition.'},
    @{Name='terrain_height'; File='terrain.c'; Old='if (flags == 2) {'; New='if (flags & 2) {'; Why='Treats other flag values containing bit two as exactly two.'},
    @{Name='actor_snapshot'; File='animation.c'; Old='W16(to + 0x50u, R16(from + 0x50u));'; New='(void)0;'; Why='Omits a snapshot word write.'},
    @{Name='ground_update'; File='animation.c'; Old='? 0xec78u : 0x1388u;'; New='? 0x1388u : 0xec78u;'; Why='Swaps the selected recoil sign.'},
    @{Name='ground_collide'; File='collision.c'; Old='(z < 0 ? -z : z) < 0x5aa'; New='(z < 0 ? -z : z) <= 0x5aa'; Why='Changes the slope boundary at exactly 0x5aa.'},
    @{Name='ground_collide'; File='collision.c'; Old='(v & 0xffff0000u) | (uint16_t)(v + damage)'; New='(uint16_t)(v + damage)'; Why='Loses the preserved high word of slide damage.'}
    @{Name='ground_effects'; File='effects.c'; Old='fx_s32(distance) < 15000'; New='fx_s32(distance) <= 15000'; Why='Includes the excluded 15000 distance boundary.'}
    @{Name='ground_effects'; File='effects.c'; Old='eax = word(eax, index);'; New='eax = index;'; Why='Drops the path-dependent upper EAX word at the loop test.'}
