    @{Name='vehicle_hit'; File='damage.c'; Old='magnitude < 0x4000,'; New='magnitude <= 0x4000,'; Why='Changes front/rear choice at the quarter-turn boundary.'}
    @{Name='vehicle_hit'; File='damage.c'; Old='uint32_t quotient = (uint32_t)(fx_s32(product) / fx_s16(range));'; New='uint32_t quotient = (uint32_t)(((fx_s32(reach) - fx_s32(lo(r))) * fx_s16(damage)) / fx_s16(range)); (void)product;'; Why='Keeps the high multiply bits discarded by the original.'}
    @{Name='building_hit'; File='damage.c'; Old='(void)invoke(g, g->random, 0, &g->generator, 1);'; New='(void)0;'; Why='Omits the apparently redundant but observable RNG advance.'}
    @{Name='building_part'; File='damage.c'; Old='if((uint16_t)lo(result)==0x100u) {'; New='if((uint16_t)lo(result)!=0x100u) {'; Why='Inverts the V40 lifecycle gate, changing callbacks and actor flags.'}
    @{Name='building_part'; File='damage.c'; Old='result=g->call_registers(g->call_context,g->unlink,&linked,1,registers);'; New='result=part_call(g,g->unlink,&linked,1); (void)registers;'; Why='Loses caller scratch registers at the real unlink callee.'}

    @{Name='projectile_def'; File='weapons.c'; Old='es2_projectile_def_registers(uint32_t base,uint8_t index) { return definition(base,index); }'; New='es2_projectile_def_registers(uint32_t base,uint8_t index) { return definition(base+1u,index); }'; Why='Offsets a definition selector by one byte.'}
