    @{Name='rtl_start_zero'; File='rtl_start.c'; Old='for (; record < end && env->read32(c, record + 2u) != 0u; record += ES2_RTL_RECORD_SIZE) {'; New='for (; record < end; record += ES2_RTL_RECORD_SIZE) { if (!env->read32(c, record + 2u)) continue;'; Why='A record with function 0 ends the scan of its table (41a6aa); skipping it instead runs the records behind it.'}
