    @{Name='rtl_start_winmain'; File='rtl_start.c'; Old='esp - 0x30u, 4u, args, &result);'; New='esp - 0x2cu, 4u, args, &result);'; Why='WinMain is entered 0x30 bytes below __startup''s entry (frame, three saved registers, four arguments, return address).'}
    @{Name='rtl_start_popped'; File='rtl_start.c'; Old='return es2_rtl_exit(rt, env, esp - 0x24u + popped, result);'; New='return es2_rtl_exit(rt, env, esp - 0x24u + popped / 2u, result);'; Why='__startup removes WinMain''s arguments again (add esp,10h at 41a812) after a stdcall WinMain popped them, so exit runs 16 bytes higher.'}
    @{Name='rtl_start_fpu'; File='rtl_start.c'; Old='(uint16_t)((ES2_RTL_FPU_DEFAULT & ES2_RTL_FPU_MASK)'; New='(uint16_t)((ES2_RTL_FPU_FNINIT & ES2_RTL_FPU_MASK)'; Why='__fpreset loads the default word 0x1332 of 421dc8 after fninit, not the fninit word 0x037f.'}
    @{Name='rtl_start_frame'; File='rtl_start.c'; Old='rt->frame_record = esp - 0xcu;'; New='rt->frame_record = esp - 0x8u;'; Why='__startup links its SEH record at ebp-8 = entry ESP - 0xc (41a726).'}
    @{Name='rtl_start_atexit'; File='rtl_start.c'; Old='if (rt->atexit_count == ES2_RTL_ATEXIT_LIMIT) return 1u;'; New='if (rt->atexit_count == ES2_RTL_ATEXIT_LIMIT - 1u) return 1u;'; Why='atexit refuses only when 32 functions are registered (cmp 20h at 419073).'}
    @{Name='rtl_start_cexit'; File='rtl_start.c'; Old='if (keep_running) return ES2_RTL_RETURNED;'; New='if (keep_running && quick) return ES2_RTL_RETURNED;'; Why='_cexit returns after the atexit functions, the exit records and the buffer flush (4191dd); it never closes the streams or calls ExitProcess.'}
    @{Name='rtl_start_abort'; File='rtl_start.c'; Old='return es2_rtl_quick_exit(rt, env, esp - 0x20u, ES2_RTL_ABORT_STATUS);'; New='return es2_rtl_quick_exit(rt, env, esp - 0x20u, ES2_RTL_ERROR_STATUS);'; Why='abort ends with _exit(3) (41905c), __ErrorExit with _exit(1).'}
    @{Name='rtl_start_signal'; File='rtl_start.c'; Old='rt->sigabrt = 0;'; New='rt->sigabrt = handler;'; Why='raise resets a user handler to the default before calling it (41a342).'}
    @{Name='rtl_start_modality'; File='rtl_start.c'; Old='if (!env->thread_has_window(c, thread)) modality = 0x1000u;'; New='if (env->thread_has_window(c, thread)) modality = 0x1000u;'; Why='On a version word with bit 31 the box is system-modal only when the thread has no window (418ed5).'}
    @{Name='rtl_start_title'; File='rtl_start.c'; Old='if (!title) title = strrchr(name, '':'');'; New='if (!title) title = strrchr(name, ''/'');'; Why='Without a backslash the title starts after the last colon of the module name (418f19).'}
    @{Name='stream_open'; File='vfs_stream.c'; Old='W32(s + ES2_VFS_S_SOURCE, R32(s + ES2_VFS_S_ARCHIVE));'; New='W32(s + ES2_VFS_S_SOURCE, 0);'; Why='A kind-2 member leaves S+0Eh zero; 47318b copies S+0Ah (the archive''s buffered stream) into it, the source every later read uses.'}
    @{Name='stream_close'; File='vfs_stream.c'; Old='W16(s + ES2_VFS_S_HANDLE, 0xffffu);'; New='W16(s + ES2_VFS_S_HANDLE, 0xfffeu);'; Why='Close leaves handle FFFEh instead of FFFFh (4730d5); later calls take the closed stream for a loose file.'}
    @{Name='stream_read'; File='vfs_stream.c'; Old='length - pos + 1u'; New='length - pos'; Why='A read past the member end delivers length-pos+1 bytes (473651 INC EDX, the suffix byte); one byte fewer changes the buffer, S+16h and S+1Ah.'}
    @{Name='stream_seek'; File='vfs_stream.c'; Old='const uint32_t apos = position < length ?'; New='const uint32_t apos = position <= length ?'; Why='Seeking to the length takes the past-end branch (JAE at 47342b: S+1Ah = length, status 2); <= keeps the stream inside.'}
    @{Name='stream_tell'; File='vfs_stream.c'; Old='out->eax = R32(s + ES2_VFS_S_SOURCE) ? R32(s + ES2_VFS_S_POS) : 0;'; New='out->eax = R32(s + ES2_VFS_S_SOURCE) ? R32(s + ES2_VFS_S_POS) : 1;'; Why='Without a source the tell is 0 (47339d XOR EAX,EAX).'}
    @{Name='stream_size'; File='vfs_stream.c'; Old='out->eax = R32(s + ES2_VFS_S_SOURCE) ? R32(s + ES2_VFS_S_LENGTH) : 0;'; New='out->eax = R32(s + ES2_VFS_S_SOURCE) ? R32(s + ES2_VFS_S_START) : 0;'; Why='The member size is S+22h (47335e), not the start offset S+12h.'}
    @{Name='vol_lookup'; File='vfs_stream.c'; Old='for (uint32_t i = 0; (uint8_t)i < R8(manager + 0x78u); ++i) {'; New='for (uint32_t i = 1; (uint8_t)i < R8(manager + 0x78u); ++i) {'; Why='The search starts at slot 0 (46806d XOR EBX,EBX); skipping it misses SIMPATCH''s members and the slot-0 winners.'}
    @{Name='member_lookup'; File='vfs_stream.c'; Old='W32(record + 8u, block + 9u);'; New='W32(record + 8u, block + 8u);'; Why='The payload start is the block offset +0Dh-4 = +9 (47cee2/47cee5); +8 points at the last metadata byte.'}
    @{Name='explosion_dtor'; File='destructors.c'; Old='r.edx=R32(VA(g,0x4a9602u));'; New='r.edx=R32(VA(g,0x4a9691u));'; Why='Appends the second link (O+53h) to the first removal list; MOV EDX,[4a9602h] at 407e92 pushes the list of the 4a95fe pool.'}
    @{Name='fire_dtor'; File='destructors.c'; Old='if(!fires) { /* 46b5a5 */'; New='if(fx_s32(fires)<=0) { /* 46b5a5 */'; Why='Stops the fire sound when the count goes negative; DEC / JNE at 46b59f..46b5a5 calls sfx_stop(33h) only when the count reaches exactly 0.'}
    @{Name='beam_dtor'; File='destructors.c'; Old='dt_call(g,0x47758cu,a,1,&r);r.ecx=a[0];'; New='dt_call(g,0x47758cu,a,1,&r);'; Why='Keeps the arena free''s ECX; POP ECX at 40bac8 reloads the pushed O+58h, which reaches 496406 as its entry ECX.'}
    @{Name='debris_dtor'; File='destructors.c'; Old='{0x498a18u,0,DT_B},         /* DEBRIS 40f7e6 */'; New='{0x498a18u,0,DT_C},         /* DEBRIS 40f7e6 */'; Why='Runs DEBRIS with the BULLET register variant; 40f7e6 decrements twice (not three times) and its epilogue loads the saved FS:0 head into EDX (40f872), not ECX.'}
    @{Name='flat_dtor'; File='destructors.c'; Old='{0x49a206u,0,DT_B},         /* FlatObj 41bd46 */'; New='{0x49a206u,0,DT_A},         /* FlatObj 41bd46 */'; Why='Runs FlatObj with the EXPLOSION register variant; 41bd46 has no decrement before its null test (41bd5c) and returns the head in EDX.'}
    @{Name='meteor_dtor'; File='destructors.c'; Old='{0x49a6ecu,0,DT_B},         /* METEOR 424034 */'; New='{0x49a6ecu,0,DT_C},         /* METEOR 424034 */'; Why='Runs METEOR with the BULLET register variant; 424034 returns the saved FS:0 head in EDX (4240c0), EAX = the counter pointer.'}
    @{Name='bullet_dtor'; File='destructors.c'; Old='else { r->eax=R32(f-4u);r->ecx=R32(r->eax);a[0]=r->eax;target=R32(r->ecx+0x18u); }'; New='else { r->eax=R32(f-4u);r->edx=R32(r->eax);a[0]=r->eax;target=R32(r->edx+0x18u); }'; Why='Loads the shape''s vtable into EDX; MOV ECX,[EAX] at 40b6ad leaves the counter pointer in EDX for the virtual +18h call.'}
    @{Name='rocket_dtor'; File='destructors.c'; Old='{0x4983a0u,0,DT_C},         /* ROCKET 40ab8d */'; New='{0x4983a0u,0,DT_B},         /* ROCKET 40ab8d */'; Why='Runs ROCKET with the DEBRIS register variant; 40ab8d decrements three times before the tail and returns the head in ECX (40ac10).'}
    @{Name='shape_dtor'; File='destructors.c'; Old='dt_call(g,0x47758cu,a,1,&r);r.ecx=block;'; New='dt_call(g,0x47758cu,a,1,&r);'; Why='Keeps the arena free''s ECX; POP ECX at 490bfd reloads the block, the entry ECX of 48be20.'}
    @{Name='shape_base_dtor'; File='destructors.c'; Old='W32(s,VA(g,0x4a6a14u));'; New='W32(s,VA(g,0x4a62edu));'; Why='Stores the shape-instance vtable; 48be32 stores the base vtable 4a6a14h.'}
    @{Name='weapon_frame'; File='weapon_slots.c'; Old='if(R8(E+0x49u)||!R8(E+0x4cu))'; New='if(R8(E+0x49u)&&!R8(E+0x4cu))'; Why='Exchanges a linked pair only when both tests hold; JNE at 410c4d (E+49h set) or a clear E+4Ch at 410c59 each lead to the exchange at 410c5b.'}
    @{Name='ready_step'; File='weapon_slots.c'; Old='if(fx_s16(k)>fx_s16(slot>>16))break;'; New='if(fx_s16(k)>=fx_s16(slot>>16))break;'; Why='Stops one step early; JLE at 410ac9 steps again while the old counter is at most the count (count + 1 steps).'}
    @{Name='selected_ready'; File='weapon_slots.c'; Old='es2_weapon_registers r={W,E,sl_lo(entry[2],i)};'; New='es2_weapon_registers r={W,E,i};'; Why='Pushes the clean index; MOV CX,[EBP+10h] at 410a25 keeps the entry ECX''s high word in the pushed slot and in ECX.'}
    @{Name='chain_ready'; File='weapon_slots.c'; Old='if(ax!=5u&&ax!=3u)'; New='if(ax!=5u)'; Why='Checks the word table for V60 = 3; the compare at 4109b4 accepts 3 like 5 without reading W+0Ah.'}
    @{Name='latch_set'; File='weapon_slots.c'; Old='return sl_pair(W+0x14u,entry[1]);'; New='return sl_pair(W,entry[1]);'; Why='Returns W; ADD EAX,14h at 410f0a leaves the latch address in EAX.'}
    @{Name='link_toggle'; File='weapon_slots.c'; Old='if(R16(cE+0x56u)!=R16(cL+0x56u))'; New='if(R8(cE+0x56u)!=R8(cL+0x56u))'; Why='Compares the carrier bytes; CMP CX,[EBX+56h] at 410f56 compares words.'}
    @{Name='member_toggle'; File='weapon_slots.c'; Old='const uint32_t c=sl_lo(index,R16(T+2u*index)^1u);'; New='const uint32_t c=R16(T+2u*index)^1u;'; Why='Clears ECX''s high word; MOV CX at 410cf0 keeps the sign of MOVSX ECX,DX (410cdb) for a negative index.'}
    @{Name='gauge_sync'; File='weapon_slots.c'; Old='a[0]=H;CALL(0x441fa4,1);r.ecx=H;'; New='a[0]=H;CALL(0x441fa4,1);'; Why='Keeps the lamp''s ECX; POP ECX at 442101 reloads H, the entry ECX of 442054 and the return ECX.'}
    @{Name='gauge_state'; File='weapon_slots.c'; Old='W8(copy+3u,R8(H+0xb4u));'; New='W8(copy+3u,R8(H+0xb3u));'; Why='Copies the lamp byte twice; 442140 copies H+B4h to 4d1a5f.'}
    @{Name='gauge_link'; File='weapon_slots.c'; Old='*ecx=a[0];'; New='*ecx=r.ecx;'; Why='Returns 410f14''s ECX; POP ECX at 44207a reloads the pushed W.'}
    @{Name='gauge_button'; File='weapon_slots.c'; Old='if(R16(H+0xb1u)==3u)W16(H+0xb1u,0);'; New='if(R16(H+0xb1u)>=3u)W16(H+0xb1u,0);'; Why='Wraps every mode above 2; CMP/JNE at 44217c..442184 clears the word only when the increment gives exactly 3.'}
    @{Name='gauge_mode'; File='weapon_slots.c'; Old='const uint32_t edx=sl_lo(entry[1],mode);'; New='const uint32_t edx=sl_lo(entry[2],mode);'; Why='Takes the high word from ECX; MOV DX,[EBP+0Ch] at 441f96 keeps the entry EDX''s high word.'},
    # The stack-coordinate shims of player_input, command_key and hud_key (live c3_09-wingman-orders, Alt+O).
    @{Name='player_input'; File='../../tools/reference-game/proxy/input_dispatch_hooks.h'; Old='        g.scratch=s->ebp-ES2_PLAYER_INPUT_SCRATCH;g.call=input_dispatch_stack_guest_call;g.context=&c;'; New='        g.scratch=s->ebp-ES2_PLAYER_INPUT_SCRATCH;g.call=input_dispatch_guest_call;g.context=&c.call;'; Why='Runs player_input''s game calls through the plain host-stack bridge again (the input_dispatch adapter): the command handler and the MFD chain below it run at another coordinate, so the group order 4231a4 reads another uninitialized priority word at EBP-1Ch for Alt+O (the live c3_09-wingman-orders difference).'}
    @{Name='player_input'; File='../../tools/reference-game/proxy/input_dispatch_hooks.h'; Old='math_native_read32(NULL,s->ebp-0x98u),a[0],r);'; New='0,a[0],r);'; Why='Passes EDI = 0 at 45feb8 and 432b14; 460870 still holds the caller''s EDI there (4608d1 XOR EDI,EDI comes after them).'}
    @{Name='player_input'; File='input_dispatch.c'; Old='SAVE(0x460d0a);CALL(0x49681a,3);'; New='SAVE(0x460d0b);CALL(0x49681a,3);'; Why='Leaves another return address in the memset slot below 460870''s outgoing ESP; 460d05 CALL leaves 00460D0Ah there, and no later call of 460870 has three slots.'}
    @{Name='command_key'; File='../../tools/reference-game/proxy/commands_hooks.h'; Old='ES2_SHIM(commands_command_key_shim,0x5feb8u,'; New='ES2_SHIM(commands_command_key_shim,0x7fffffffu,'; Why='Installs command_key without its entry shim: the commands host-stack bridge runs 49630c, 432bc8 and the MFD chain at another coordinate with a synthetic EBP.'}
    @{Name='command_key'; File='../../tools/reference-game/proxy/commands_hooks.h'; Old='math_native_read32(NULL,s->ebp-0x60u),'; New='0,'; Why='Passes EBX = 0 at 49630c and 432bc8; 45feb8 still holds the caller''s EBX there (45fefa XOR EBX,EBX comes after them).'}
    @{Name='command_key'; File='commands.c'; Old='player?0x460844u:0x460857u'; New='player?0x460845u:0x460857u'; Why='Leaves another return address below the key method''s slots; 460841 CALL [EDX+2Ch] leaves 00460844h, the last call of 45feb8 on that path.'}
    @{Name='hud_key'; File='../../tools/reference-game/proxy/hud_keys_hooks.h'; Old='ES2_SHIM(hud_keys_hud_key_shim,0x32bc8u,'; New='ES2_SHIM(hud_keys_hud_key_shim,0x7fffffffu,'; Why='Installs hud_key without its entry shim: the hud_keys host-stack bridge runs 446c38 and the group order 4231a4 at another coordinate, which reads another uninitialized priority word for Alt+O.'}
    @{Name='hud_key'; File='hud_keys.c'; Old='hk_at(s,ret,1,request);'; New='hk_at(s,ret,0,request);'; Why='Calls the getter 429820 at the outgoing ESP; the original has pushed the request for 42a3f4 first (432d22, 432e1b, ...), so 429820 is entered 4 bytes lower.'}
    @{Name='hud_key'; File='hud_keys.c'; Old='r.eax=kc<=0xeu?kc-0xcu:kc<=0x27u?kc-0x1cu:kc<=0x44u?kc-0x43u:kc-0x220u;'; New='r.eax=kc;'; Why='Enters 446c38 with EAX = the key code; the compare chain leaves its remainder there (Alt+O: 218h-57h-1C9h = FFFFFFF8h at 432c7e).'}
    @{Name='hud_key'; File='hud_keys.c'; Old='const uint32_t stepped=M<=1u?M-1u:M-4u;'; New='const uint32_t stepped=M-4u;'; Why='The Esc/F1-F6 dispatch leaves ESI = M-1 for modes 0 and 1 (432ceb SUB ESI,1 / JB, JE); M-4 reaches the request calls in another ESI.'},
    @{Name='rtl_io_open'; File='rtl_io.c'; Old='else if (x == 0x200u) disposition = 5u;'; New='else if (x == 0x200u) disposition = 4u;'; Why='O_TRUNC alone (0x200) opens with TRUNCATE_EXISTING (409dd1 -> 409e04, edi 5), not OPEN_ALWAYS.'}
    @{Name='rtl_io_close'; File='rtl_io.c'; Old='w32(c, c->l->handles + 4u * fd, 0xffffffffu);'; New='w32(c, c->l->handles + 4u * fd, 0u);'; Why='A closed handle slot holds -1 (409aa9), not 0.'}
    @{Name='rtl_io_read'; File='rtl_io.c'; Old='if (z || k) return total;'; New='if (z) return total;'; Why='A text read returns after the first round that kept bytes (408220 test eax,eax; jne); reading on fills more of the buffer.'}
    @{Name='rtl_io_write'; File='rtl_io.c'; Old='out[produced++] = ''\r'';'; New='out[produced++] = ''\n'';'; Why='A text write turns LF into CR LF (4082cb mov byte [esi],0dh).'}
    @{Name='rtl_io_lseek'; File='rtl_io.c'; Old='if (whence > 2u) return io_error(c, 1);'; New='if (whence > 2u) return io_error(c, 6);'; Why='An invalid whence sets the DOS error 1 (409d48 push 1), not 6.'}
    @{Name='rtl_io_filelength'; File='rtl_io.c'; Old='if (size == 0xffffffffu) size = nt_error(c);'; New='if (size == 0xffffffffu) size = 0xffffffffu;'; Why='A failed GetFileSize sets errno from GetLastError (408b5a call 4091bc).'}
    @{Name='rtl_io_fopen'; File='rtl_io.c'; Old='else if (ch == ''w'') { of = 0x301u; pm = 0x80u; f = 2; }'; New='else if (ch == ''w'') { of = 0x201u; pm = 0x80u; f = 2; }'; Why='Mode w opens with O_CREAT|O_TRUNC|O_WRONLY 0x301 (4058c2), not 0x201.'}
    @{Name='rtl_io_fclose'; File='rtl_io.c'; Old='uint32_t result = io_close(c, f_fd(c, fp));'; New='uint32_t result = io_close(c, f_fd(c, fp)) + 1u;'; Why='fclose returns the result of close (4055ae mov esi,eax), 0 on success.'}
    @{Name='rtl_io_fread'; File='rtl_io.c'; Old='uint32_t chunk = left - left % bsize;'; New='uint32_t chunk = left;'; Why='fread reads whole buffers directly (405c24 div: left - left mod bsize) and the rest through the buffer.'}
    @{Name='rtl_io_fwrite'; File='rtl_io.c'; Old='if (level == 0) w32(c, fp + F_LEVEL, 0xffffffffu - bsize);'; New='if (level == 0) w32(c, fp + F_LEVEL, 0u - bsize);'; Why='An empty output buffer has level -1-bsize (405b0e or edx,-1; sub edx,eax), not -bsize.'}
    @{Name='rtl_io_fseek'; File='rtl_io.c'; Old='f_set_flags(c, fp, f_flags(c, fp) & 0xfe5fu);'; New='f_set_flags(c, fp, f_flags(c, fp) & 0xfe7fu);'; Why='fseek clears the end-of-file flag 0x20 too (405e07 and 0fe5fh).'}
    @{Name='rtl_io_ftell'; File='rtl_io.c'; Old='if (s32(r32(c, fp + F_LEVEL)) >= 0) return at - buffered_count(c, fp);'; New='if (s32(r32(c, fp + F_LEVEL)) >= 0) return at + buffered_count(c, fp);'; Why='For input the buffered bytes are subtracted from the file position (405ead sub esi,eax).'}
    @{Name='rtl_io_rewind'; File='rtl_io.c'; Old='if (*eax == 0) f_set_flags(c, a0, f_flags(c, a0) & ~0x10u);'; New='if (*eax == 0) f_set_flags(c, a0, f_flags(c, a0) & ~0x20u);'; Why='rewind clears the error flag 0x10 (406628 and 0ffefh); fseek has cleared 0x20 already.'}
    @{Name='rtl_io_fscanf'; File='rtl_io.c'; Old='if (s32(base) <= s32(d)) break;'; New='if (s32(base) < s32(d)) break;'; Why='A digit equal to the base ends the number (406d4e cmp esi,[ebp-18h]; jle): 8 in octal, 9 never in decimal input.'}
    @{Name='rtl_io_flushall'; File='rtl_io.c'; Old='if ((f_flags(c, fp) & 3u) && r32(c, fp + F_LEVEL)) { f_flush(c, fp); ++count; }'; New='if (f_flags(c, fp) & 3u) { f_flush(c, fp); ++count; }'; Why='flushall counts and flushes only streams with buffered data (407d80 cmp [ebx+8],0).'}
    @{Name='rtl_io_findfirst'; File='rtl_io.c'; Old='if (node) os1(c, ES2_IO_OS_FIND_CLOSE, r32(c, node + 4u));'; New='if (node) {}'; Why='A find block used again closes its old search first (40870f FindClose).'}
    @{Name='rtl_io_findnext'; File='rtl_io.c'; Old='if (!(attributes & 0x16u)) break;'; New='if (!(attributes & 0x14u)) break;'; Why='Hidden, system and directory entries (0x16, 4087ee) need their bit in the mask; hidden files would pass.'}
    @{Name='rtl_io_time'; File='rtl_io.c'; Old='limit -= total % 7u;'; New='limit -= total % 6u;'; Why='The summer-time limit is the Sunday on or before the reference day (41e4c1 div by 7).'}
    @{Name='rtl_io_printf'; File='rtl_io.c'; Old='*eax = regs.eax;'; New='*eax = regs.eax + 1u;'; Why='The printf stub returns the number of characters formatted (vprinter 407c2b), as the export does when stdout accepts them.'}
    @{Name='rtl_io_fputc'; File='rtl_io.c'; Old='case ES2_IO_FPUTC: *eax = a0 & 0xffu; return ES2_IO_DONE;'; New='case ES2_IO_FPUTC: *eax = a0 & 0x7fu; return ES2_IO_DONE;'; Why='The __fputc stub returns the character as an unsigned byte (40631b, al from [ebp-1]).'}
    @{Name='rtl_io_fputs'; File='rtl_io.c'; Old='*eax = n ? r8(c, a0 + n - 1u) : 0u;'; New='*eax = n ? r8(c, a0) : 0u;'; Why='The fputs stub returns the last character of the string (405ba9 mov al,[ebx+esi-1]).'}
    @{Name='collision_walk'; File='obstacle.c'; Old='if(fx_s32(r.eax)<fx_s32(r.ecx)) {'; New='if(fx_s32(r.eax)<=fx_s32(r.ecx)) {'; Why='Counts a distance equal to the shape radius as inside; JGE at 427cb2 skips it.'},
    @{Name='collision_walk'; File='obstacle.c'; Old='r.edx=ob_lo(r.edx,i);'; New='r.edx=i;'; Why='Clears the high word of EDX after an entry; MOV DX at 427d69 keeps the last callee''s, which a walk without a hit returns.'},
    @{Name='shape_cell'; File='obstacle.c'; Old='r.edx=ob_sx(R16(f-4u));'; New='r.edx=R16(f-4u);'; Why='Zero-extends the shifted x origin word; MOVSX at 4273a1 sign-extends it into Q.x and the high word of the third cell slot.'},
    @{Name='convoy_leader'; File='convoy.c'; Old='if(!R8(edx+0xa4u)&&!R8(edx+0x99u))'; New='if(!R8(edx+0xa4u))'; Why='Ignores byte +99h; 46a5ef rejects a member whose +99h is set.'}
