# Every descriptor must have a real, independently compiled mutation.
$registry=[IO.File]::ReadAllText((Join-Path $repo 'tools/reference-game/proxy/hook_registry.h'))
$names=@([regex]::Matches($registry,'ES2_HOOK\((\w+),') | ForEach-Object { $_.Groups[1].Value })
foreach($name in $names) { if($name -notin $cases.Name) { throw "Missing mutation for $name" } }
if ($Only) { $cases=@($cases | Where-Object { $Only -contains $_.Name }) }
if (!$cases.Count) { throw 'No mutation cases selected.' }
# A separate workspace reuses the real Bazel targets, pinned module lock and
# exact harness link line. Only our source is copied, never a dependency or
# game file. Disable every scratch BUILD file on exit so //... cannot discover
# mutant targets (also after a failed build/check).
$workspace=Join-Path $output ('mutation-workspace-'+[Guid]::NewGuid().ToString('N'))
New-Item -ItemType Directory -Path $workspace | Out-Null
foreach($name in @('MODULE.bazel','MODULE.bazel.lock','.bazelrc','BUILD.bazel')) {
    Copy-Item -LiteralPath (Join-Path $repo $name) -Destination (Join-Path $workspace $name)
}
# platform: the proxy's adapters link //platform:os. sim: the sim suites'
# binaries in the invitro package link it (suites.bzl);
# the hook-group harness built here does not.
foreach($folder in @('core','hook','rtl','bazel','platform','tools/reference-game/proxy','tools/reference-game/invitro','formats','sim')) {
    $destination=Join-Path $workspace $folder
    New-Item -ItemType Directory -Force -Path ([IO.Path]::GetDirectoryName($destination)) | Out-Null
    Copy-Item -LiteralPath (Join-Path $repo $folder) -Destination $destination -Recurse
}
# MODULE.bazel loads the @es2_data rule from tools/reference-game.
foreach($name in @('BUILD.bazel','data_inputs.bzl','data_inputs.py')) {
    Copy-Item -LiteralPath (Join-Path $repo ('tools/reference-game/'+$name)) -Destination (Join-Path $workspace ('tools/reference-game/'+$name))
}
$buildFiles=@(Get-ChildItem -LiteralPath $workspace -Recurse -File -Filter BUILD.bazel)
$results=@()
Push-Location $workspace
$startupArgs=@()
if ($BazelOutputBase) { $startupArgs+=('--output_base='+[IO.Path]::GetFullPath($BazelOutputBase).Replace('\','/')) }
$cacheArgs=@()
if ($RepoContentsCache) { $cacheArgs+=('--repo_contents_cache='+[IO.Path]::GetFullPath($RepoContentsCache).Replace('\','/')) }
try {
foreach ($case in $cases) {
    $run=Join-Path $output ('mutation-'+$case.Name+'-'+[Guid]::NewGuid().ToString('N'))
    New-Item -ItemType Directory -Path $run | Out-Null
    $file=Join-Path $workspace ('core/src/'+$case.File)
    $source=[IO.File]::ReadAllText((Join-Path $repo ('core/src/'+$case.File)))
    # After: a text occurring once in the file; the site is the first Old behind it
    # (for Old texts that repeat verbatim in other functions).
    if ($case.After) {
        $anchor=$source.IndexOf($case.After,[StringComparison]::Ordinal)
        if ($anchor -lt 0 -or $source.IndexOf($case.After,$anchor+1,[StringComparison]::Ordinal) -ge 0) {throw "Mutation anchor is not unique: $($case.Name)"}
        $site=$source.IndexOf($case.Old,$anchor,[StringComparison]::Ordinal)
        if ($site -lt 0) {throw "Mutation site not found: $($case.Name)"}
    } else {
        if (($source.Split([string[]]@($case.Old),[StringSplitOptions]::None).Count-1) -ne 1) {throw "Mutation site is ambiguous: $($case.Name)"}
        $site=$source.IndexOf($case.Old,[StringComparison]::Ordinal)
    }
    [IO.File]::WriteAllText($file,$source.Substring(0,$site)+$case.New+$source.Substring($site+$case.Old.Length))
    $ErrorActionPreference='Continue' # Native stderr is progress; exit status decides success.
    & $Bazel @startupArgs build //tools/reference-game/invitro:differential_harness --lockfile_mode=error @cacheArgs *> (Join-Path $run 'build.log')
    $buildStatus=$LASTEXITCODE
    $ErrorActionPreference='Stop'
    [IO.File]::WriteAllText($file,$source)
    if($buildStatus) {throw "Mutant build failed; not a detected mutation. See $run/build.log"}
    $ErrorActionPreference='Continue'
    $bin=(& $Bazel @startupArgs info bazel-bin --lockfile_mode=error @cacheArgs 2> (Join-Path $run 'info.log') | Select-Object -Last 1).Trim()
    $infoStatus=$LASTEXITCODE
    $ErrorActionPreference='Stop'
    if($infoStatus) { throw 'Cannot locate the Bazel mutant output.' }
    $exe=Join-Path $run 'mutant.exe'
    Copy-Item -LiteralPath (Join-Path $bin 'tools/reference-game/invitro/differential_harness.exe') -Destination $exe
    $log=Join-Path $run 'result.log'
    $ErrorActionPreference='Continue'
    & $exe $case.Name *> $log
    $status=$LASTEXITCODE
    $ErrorActionPreference='Stop'
    $failure=Select-String -LiteralPath $log -Pattern ('FAIL: '+$case.Name+' case \d+')
    if($status -eq 0 -or !$failure) {throw "Mutation was not caught: $($case.Name) ($status)"}
    $witness=@($failure)[0].Line
    $number=[regex]::Match($witness,('FAIL: '+$case.Name+' case (\d+)')).Groups[1].Value
    $results+=@{Name=$case.Name; Case=[uint32]$number; Why=$case.Why; Evidence=$run; Failure=$witness}
    $results | ConvertTo-Json -Depth 3 | Set-Content -LiteralPath (Join-Path $workspace 'mutation-results.json')
    Write-Output "PASS: $($case.Name) mutation caught: $witness"
    Write-Output "Why non-equivalent: $($case.Why)"
    Write-Output "Evidence: $run"
}
Write-Output "Mutation summary: $workspace/mutation-results.json"
} finally {
    # Without -BazelOutputBase the workspace's unique path gives it its own output
    # base; stop that server instead of leaving it idle for hours.
    if (!$BazelOutputBase) {
        $ErrorActionPreference='Continue'
        & $Bazel shutdown *> $null
        $ErrorActionPreference='Stop'
    }
    Pop-Location
    foreach($build in $buildFiles) {
        Move-Item -LiteralPath $build.FullName -Destination ($build.FullName+'.inactive')
    }
}
# Expected mutant failures must not leak a nonzero native status to a caller
# after every required witness has succeeded. Exceptions skip this statement.
$global:LASTEXITCODE=0
